"""Closed, free review learning with platform grading of eight first verdicts."""
import copy,json
from build_projects import Drafts,WORK,save_json
from remove_bbox_image_error import upload_once
F=WORK/'state/review_learning_gate'
FIELDS=['public_name','public_description','public_instructions','private_comment','task_spec','assignments_issuing_type','assignments_automerge_enabled']
def main():
 d=Drafts();F.mkdir(exist_ok=True);path=F/'migration.json';m=json.loads(path.read_text()) if path.exists() else {}
 if not (F/'before.json').exists():
  ids=copy.deepcopy(d.state['objects']);old=d.api.get('trainings/'+ids['review_training']);exam=d.api.get('pools/'+ids['review_exam']);work=d.api.get('pools/'+ids['review_main']);assert all(x['status']=='CLOSED' for x in [old,exam,work]);assert not d.api.all('assignments',pool_id=old['id']);assert not d.api.all('assignments',pool_id=exam['id'])
  save_json(F/'before.json',{'ids':ids,'project':d.api.get('projects/'+ids['review_project']),'training':old,'exam':exam,'main':work,'tasks':d.api.all('tasks',pool_id=old['id'])})
 b=json.loads((F/'before.json').read_text());ids=b['ids'];assert len(b['tasks'])==8
 if 'gate_id' not in m:
  name='ДЗ5 review: обучение 7 из 8 первых вердиктов';found=[x for x in d.api.all('skills') if x['name']==name];assert len(found)<=1;s=found[0] if found else d.api.post('skills',{'name':name,'hidden':True,'private_comment':'Platform GOLDEN_SET: >=7/8 first verdicts; learning gate only.'});m['gate_id']=s['id'];save_json(path,m)
 project={k:copy.deepcopy(b['project'][k]) for k in FIELDS if k in b['project']};spec=project['task_spec'];spec['input_spec']['review_learning_ui']={'type':'string','required':True,'hidden':True,'allowed_values':['first_verdict_v1']};spec['input_spec']['reference_status']={'type':'string','required':True,'hidden':False,'allowed_values':['accept','reject']}
 spec['output_spec']={'status':{'type':'string','required':True,'allowed_values':['accept','reject']},'draft_status':{'type':'string','required':False},'feedback_seen':{'type':'boolean','required':True},'understood':{'type':'boolean','required':True}}
 ui=WORK/'review_learning_ui';spec['view_spec']={'type':'classic','markup':(ui/'lesson.html').read_text(),'script':(ui/'lesson.js').read_text(),'styles':(ui/'lesson.css').read_text(),'assets':{'script_urls':['$TOLOKA_ASSETS/js/toloka-handlebars-templates.js']},'settings':{'showSkip':False,'showFinish':True,'showSubmit':True,'showTimer':True,'showTitle':True,'showInstructions':True,'showFullscreen':True,'showMessage':True}}
 project['public_instructions']='<p><strong>Обучение review.</strong> На странице восемь примеров. Сначала выберите свой вердикт и нажмите «Проверить ответ». Подсказка появится всегда — при верном и неверном ответе. Первый вердикт после этого изменить нельзя. Ответьте на каждый пример и ознакомьтесь с подсказкой. Затем отправьте всю страницу. Для доступа к экзамену нужны минимум 7 правильных первых ответов из 8. Причины ошибок не оцениваются.</p>'+project['public_instructions']
 if 'pool_id' not in m:
  d.api.request('PUT','/api/v1/projects/'+ids['review_project'],body=project);save_json(F/'project.json',project)
  payload={'project_id':ids['review_project'],'private_name':'Обучение review: 7/8 первых ответов, подсказка после ответа','private_comment':'review-first-verdict-learning-v1','public_description':'8 бесплатных примеров. Самостоятельный первый вердикт, затем подсказка. Допуск к экзамену при 7/8.','will_expire':b['exam']['will_expire'],'reward_per_assignment':0,'type':'TRAINING','assignment_max_duration_seconds':3600,'auto_accept_solutions':True,'defaults':{'default_overlap_for_new_task_suites':1},'filter':{'and':[{'category':'profile','key':'languages','operator':'IN','value':'RU'}]+[{'category':'skill','key':x,'operator':'EQ','value':None} for x in [ids['bbox_skill'],ids['review_skill'],m['gate_id']]]},'quality_control':{'configs':[{'collector_config':{'type':'GOLDEN_SET','parameters':{'history_size':8}},'rules':[{'conditions':[{'key':'golden_set_answers_count','operator':'EQ','value':8},{'key':'golden_set_correct_answers_rate','operator':'GTE','value':87}],'action':{'type':'SET_SKILL','parameters':{'skill_id':m['gate_id'],'skill_value':100}}}]}]}}
  matches=[x for x in d.api.all('pools',project_id=ids['review_project']) if x.get('private_comment')==payload['private_comment']];assert len(matches)<=1;p=matches[0] if matches else d.api.post('pools',payload);m['pool_id']=p['id'];save_json(path,m);save_json(WORK/'configs/review_training.json',payload)
 tasks=[]
 for old in b['tasks']:
  v=copy.deepcopy(old['input_values']);known=copy.deepcopy(old['known_solutions']);assert set(known[0]['output_values'])=={'status'};assert v.get('training_hint');v.update(review_learning_ui='first_verdict_v1',reference_status=known[0]['output_values']['status']);tasks.append({'input_values':v,'known_solutions':known})
 suite={'pool_id':m['pool_id'],'tasks':tasks,'infinite_overlap':True};key='review_learning_first_verdict_v1';d.state['objects'][key]=m['pool_id'];upload_once(d,key,'task-suites',[suite]);actual=d.api.all('task-suites',pool_id=m['pool_id']);assert len(actual)==1 and len(actual[0]['tasks'])==8 and actual[0]['infinite_overlap'];assert [x['input_values'] for x in actual[0]['tasks']]==[x['input_values'] for x in tasks];assert [x['known_solutions'] for x in actual[0]['tasks']]==[x['known_solutions'] for x in tasks];save_json(WORK/'state/quality_suites_review_training.json',actual)
 exam=copy.deepcopy(b['exam']);exam={k:v for k,v in exam.items() if k not in ['id','status','owner','created','last_started','last_stopped','last_close_reason']};exam['quality_control'].pop('training_requirement',None);exam['filter']['and']=[x for x in exam['filter']['and'] if x.get('key')!=m['gate_id']]+[{'category':'skill','key':m['gate_id'],'operator':'EQ','value':100}];d.api.request('PUT','/api/v1/pools/'+ids['review_exam'],body=exam);save_json(WORK/'configs/review_exam.json',exam)
 state=json.loads(d.state_path.read_text());state['objects'].update(review_training=m['pool_id'],review_training_gate=m['gate_id']);state['review_training_collection']='pools';save_json(d.state_path,state);save_json(WORK/'configs/review_project.json',project)
 p=d.api.get('pools/'+m['pool_id']);assert p['status']=='CLOSED';e=d.api.get('pools/'+ids['review_exam']);assert e['status']=='CLOSED';assert e['quality_control']['configs']==b['exam']['quality_control']['configs'];w=d.api.get('pools/'+ids['review_main']);assert w==b['main'];assert len(d.api.all('tasks',pool_id=w['id']))==430
 old_id=ids['review_training'];old=d.api.get('trainings/'+old_id)
 if old['status']!='ARCHIVED':d.api.post('trainings/'+old_id+'/archive')
 m.update(old_training_archived=old_id,done=True);save_json(path,m);save_json(WORK/'state/review_training.json',p);save_json(WORK/'state/review_exam.json',e);save_json(WORK/'state/review_project.json',d.api.get('projects/'+ids['review_project']));save_json(F/'verification.json',{'pool_id':m['pool_id'],'gate_id':m['gate_id'],'exam_id':e['id'],'main_id':w['id'],'all_closed':True,'examples':8,'pass_count':7,'grading':'native GOLDEN_SET, status only; no local script','exam_gate':e['filter'],'main_unchanged':True,'moderation_submitted':False});print(json.dumps(m),flush=True)
if __name__=='__main__':main()
